(7259940, 1126451, 76335, '<td valign="top">An interesting slice of life obfuscated somewhat by the fact that it looks like you''re hiding in the bushes.</td>', 'An interesting slice of life obfuscated somewhat by the fact that it looks like you''re hiding in the bushes.', '2014-09-06 13:46:00.000000', NULL, 1),
